using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata retrieval — GetTypeInfo<T>()
//    Returns JsonTypeInfo<T> directly, no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata  : {personInfo.Type.Name}  (JsonTypeInfo<{personInfo.Type.Name}>)");

var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized with it  : {json}");

Person roundTripped = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized back   : {roundTripped}");

// 2. Probe without throwing — TryGetTypeInfo()
//    Returns false instead of throwing when metadata isn't available.
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {info!.Type.Name}");
}

// Use a resolver that knows about nothing — Widget will NOT be resolvable.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite
};

if (limited.TryGetTypeInfo(typeof(Widget), out _))
{
    Console.WriteLine("Widget metadata found (unexpected)");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo(Widget) returned false — no exception thrown.");
}

public record Person(string Name, int Age);
public record Widget(int Id);

